// Slow (about 2.5 min of real time: it runs research/probe.py against the fake over TLS), so it runs
// in `npm run test:slow` and `npm run check`, not in `npm test`.
// TESTING.md L0.C2: research/probe.py, pointed at the fake over TLS, gets the same ack sequence and
// reasons as the live probe did for S1 and S3-S8. Also the TLS transport itself.
//
// The probe runs in real time (it sleeps and waits on the wall clock), so this test takes a couple
// of minutes. It is interrupted when S9 starts: S9 waits up to 240 s for a frozen truck, which the
// fake has no injector for until milestone 2, and S9 is outside L0.C2. SIGINT runs the probe's own
// cleanup. The probe's environment is built here from scratch, so it can only reach 127.0.0.1.
//
// The comparison reads the probe's raw output file, never its printout (AI_LOG.md entry 1), and
// pairs each ack with the latest send of its command_id before it in the file, never by counting.
import { test, type TestContext } from 'node:test';
import assert from 'node:assert/strict';
import { spawn, spawnSync } from 'node:child_process';
import { copyFileSync, existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { connect } from 'node:tls';
import { SystemClock } from '../src/clock.ts';
import type { CommandAck, GatewayMessage, Hello, LeaseEvent, Telemetry } from '../src/protocol.ts';
import { buildSite } from '../src/site.ts';
import { FakeGateway } from '../fake/gateway.ts';
import { DLH1 } from '../fake/dlh1.ts';
import { listenTls } from '../fake/tls.ts';

const ROOT = new URL('../', import.meta.url).pathname;
const has = (cmd: string, arg: string) => !spawnSync(cmd, [arg], { stdio: 'ignore' }).error;
const HAVE_OPENSSL = has('openssl', 'version');
const HAVE_PYTHON = has('python3', '--version');

// A throwaway key and certificate for 127.0.0.1, made at test time and deleted after.
function makeCert(t: TestContext): { dir: string; key: Buffer; cert: Buffer; certPath: string } {
  const dir = mkdtempSync(join(tmpdir(), 'fake-gw-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const r = spawnSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '1', '-subj', '/CN=127.0.0.1',
    '-addext', 'subjectAltName=IP:127.0.0.1', '-keyout', join(dir, 'key.pem'), '-out', join(dir, 'cert.pem')], { stdio: 'pipe' });
  assert.equal(r.status, 0, `openssl failed: ${r.stderr}`);
  return { dir, key: readFileSync(join(dir, 'key.pem')), cert: readFileSync(join(dir, 'cert.pem')), certPath: join(dir, 'cert.pem') };
}

test('TLS transport: auth, hello, a command and its ack as NDJSON; an over-long line closes the connection', { skip: !HAVE_OPENSSL }, async (t) => {
  const { key, cert } = makeCert(t);
  const gw = new FakeGateway(new SystemClock(), { seed: 3, site: DLH1, blasts: 'none' });
  gw.start();
  const server = await listenTls(gw, { key, cert });
  t.after(async () => { gw.stop(); await server.close(); });

  const sock = connect({ host: '127.0.0.1', port: server.port, ca: cert });
  const lines: string[] = [];
  let buf = '';
  sock.on('data', (d: Buffer) => {
    buf += d.toString('utf8');
    for (let i = buf.indexOf('\n'); i >= 0; i = buf.indexOf('\n')) { lines.push(buf.slice(0, i)); buf = buf.slice(i + 1); }
  });
  const closed = new Promise<void>((resolve) => sock.on('close', () => resolve()));
  const waitFor = async (pred: (m: GatewayMessage) => boolean) => {
    for (let i = 0; i < 100; i++) {
      const found = lines.map((l) => JSON.parse(l) as GatewayMessage).find(pred);
      if (found) return found;
      await new Promise((r) => setTimeout(r, 20));
    }
    throw new Error('timed out');
  };
  await new Promise<void>((resolve) => sock.once('secureConnect', () => resolve()));
  sock.write(JSON.stringify({ type: 'auth', email: '<redacted-email>' }) + '\n');
  const hello = await waitFor((m) => m.type === 'hello') as Hello;
  assert.equal(hello.site_id, DLH1.site_id);
  sock.write(JSON.stringify({ type: 'command', command_id: 'tls-1', vehicle_id: DLH1.vehicles[0], action: 'HOLD', operator_id: 'op' }) + '\n');
  const ack = await waitFor((m) => m.type === 'command_ack') as CommandAck;
  assert.equal(ack.command_id, 'tls-1');
  assert.equal(ack.status, 'ACCEPTED');
  await waitFor((m) => m.type === 'telemetry');
  sock.write('x'.repeat(70 * 1024) + '\n');
  await closed;
});

// ---- the probe ----

type Rec = { kind: string; rx_ms: number; name?: string; raw?: string; m?: GatewayMessage };

// What the live probe got (research/README.md "Verified", fixtures accepted-then-ignored-resume and
// reverse-exit-zone), and what the spec says where the live run lost the ack or left no record.
// Each entry: [action, 'ACCEPTED' or the rejection reason].
const EXPECTED: Record<string, Array<[string, string]>> = {
  // live: the first HOLD's ack was lost on the radio; the fake has no loss in milestone 1, so the
  // spec's ACCEPTED. Resend: original ACCEPTED (verified). Reuse: COMMAND_ID_REUSED (verified).
  S1: [['HOLD', 'ACCEPTED'], ['HOLD', 'ACCEPTED'], ['RESUME', 'COMMAND_ID_REUSED'], ['RESUME', 'ACCEPTED']],
  S3: [['EXIT_ZONE', 'ACCEPTED'], ['RESUME', 'ACCEPTED']], // live: probe-119b43-5 and -6, both ACCEPTED
  // live: TAKE_CONTROL ACCEPTED with lease details, HOLD LEASE_HELD (holder probe), RESUME ACCEPTED

// One-dimensional geometry on the loop (TESTING.md L2.1-L2.6). Positions are metres along the
// loop; everything wraps at the loop length, which comes from hello. A Range is closed at both
// ends: a range that touches a zone's boundary counts as inside it, because "might be inside" is
// the safe reading (CLAUDE.md invariant 6).
import { PARAMS } from './params.ts';
import type { Direction } from './protocol.ts';
import type { Range, Site } from './site.ts';

export function normalise(loopM: number, p: number): number {
  if (p >= 0 && p < loopM) return p;
  const r = ((p % loopM) + loopM) % loopM;
  return r === loopM ? 0 : r;
}

// Distance travelling forward (increasing position) from `from` to `to`, in [0, loop).
export function forwardDistance(loopM: number, from: number, to: number): number {
  return normalise(loopM, to - from);
}

export interface ZoneExit {
  zoneId: string;
  fwdM: number; // distance forward to the end of the zone's stretch containing the position
  revM: number; // distance back to its start
  fwdBoundaryM: number; // loop position of each boundary
  revBoundaryM: number;
  direction: Direction; // the nearer boundary; a tie goes forward, the normal direction of travel
  distanceM: number;
}

// Where the nearest way out of the zone at `positionM` is.
export function zoneExit(site: Site, positionM: number): ZoneExit | undefined {
  const L = site.loopLengthM;
  const p = normalise(L, positionM);
  const zone = site.zoneAt(p);
  if (!zone) return undefined;
  for (const r of zone.ranges) {
    const into = forwardDistance(L, r.startM, p);
    if (into < r.lengthM || (r.lengthM >= L)) {
      const revM = into;
      const fwdM = r.lengthM - into;
      const direction: Direction = fwdM <= revM ? 'FWD' : 'REV';
      return {
        zoneId: zone.zoneId, fwdM, revM,
        fwdBoundaryM: normalise(L, r.startM + r.lengthM), revBoundaryM: normalise(L, r.startM),
        direction, distanceM: Math.min(fwdM, revM),
      };
    }
  }
  return undefined;
}

export interface ClearOptions {
  loaded: boolean;
  direction: Direction;
  speedMps?: number; // overrides the parameter, e.g. the pessimistic loaded reverse speed (L0.P)
  delayMs?: number; // overrides the supervisory command delay
}

// Time for a truck to cover `distanceM` under a supervisory command: speed by load and direction
// (autonomous forward, EXIT_ZONE reverse), plus the time the command takes to take effect.
export function timeToClearMs(distanceM: number, o: ClearOptions): number {
  const speed = o.speedMps ?? speedFor(o.loaded, o.direction);
  const delay = o.delayMs ?? PARAMS.supervisoryDelayMax.value;
  return (Math.max(0, distanceM) / speed) * 1000 + delay;
}

function speedFor(loaded: boolean, direction: Direction): number {
  if (direction === 'FWD') return loaded ? PARAMS.autoSpeedLoaded.value : PARAMS.autoSpeedEmpty.value;
  return loaded ? PARAMS.reverseSpeedLoaded.value : PARAMS.reverseSpeedEmpty.value;
}

// Everywhere a truck could be `elapsedMs` after it was at `anchorM`, moving forward at up to
// `fwdMps` or back at up to `revMps`. Never more than the whole loop.
export function reachableRange(loopM: number, anchorM: number, elapsedMs: number, fwdMps: number, revMps: number): Range {
  const t = Math.max(0, elapsedMs) / 1000;
  const back = Math.max(0, revMps) * t;
  const ahead = Math.max(0, fwdMps) * t;
  if (back + ahead >= loopM) return { startM: 0, lengthM: loopM };
  return { startM: normalise(loopM, anchorM - back), lengthM: back + ahead };
}

// Closed-interval overlap on the loop, with wrap.
export function rangesOverlap(loopM: number, a: Range, b: Range): boolean {
  if (a.lengthM >= loopM || b.lengthM >= loopM) return true;
  const a0 = normalise(loopM, a.startM), a1 = a0 + a.lengthM;
  const b0 = normalise(loopM, b.startM), b1 = b0 + b.lengthM;
  for (const shift of [-loopM, 0, loopM]) {
    if (a0 <= b1 + shift && b0 + shift <= a1) return true;
  }
  return false;
}

// Zone ids the range touches, in route order.
export function zonesOverlapping(site: Site, range: Range): string[] {
  return site.zones.filter((z) => z.ranges.some((r) => rangesOverlap(site.loopLengthM, range, r))).map((z) => z.zoneId);
}
// The median of other trucks' rates, if there are enough of them.
export function fleetMedianExcluding(rates: Array<{ id: string; rate: number | null }>, self: string): number | null {
  const others = rates.filter((r) => r.id !== self && r.rate !== null).map((r) => r.rate!);
  return others.length >= PARAMS.fleetMinTrucks.value ? median(others) : null;
}

export interface PathLegs { distanceM: number; emptyM: number; loadedM: number }

// Shorter way to the nearest bay: forward to a bay's start or back to its end. Zero inside one.
export function shorterWayToBay(site: Site, positionM: number): { direction: Direction; distanceM: number } | null {
  const L = site.loopLengthM;
  const bays = site.bayZones().flatMap((z) => z.ranges);
  if (bays.length === 0) return null;
  const p = normalise(L, positionM);
  let fwd = Infinity, rev = Infinity;
  for (const r of bays) {
    if (forwardDistance(L, r.startM, p) < r.lengthM) return { direction: 'FWD', distanceM: 0 };
    fwd = Math.min(fwd, forwardDistance(L, p, r.startM));
    rev = Math.min(rev, forwardDistance(L, normalise(L, r.startM + r.lengthM), p));
  }
  return fwd <= rev ? { direction: 'FWD', distanceM: fwd } : { direction: 'REV', distanceM: rev };
}

// The autonomous duty cycle forward from `positionM` to the next arrival at a bay: a truck becomes
// loaded at the end of a load segment and empty at the end of a dump segment (PROTOCOL.md §3; kinds
// come from hello). A truck starting inside a bay first leaves it.
export function dutyCycleToBay(site: Site, positionM: number, loaded: boolean): PathLegs | null {
  const L = site.loopLengthM;
  const segs = site.segments;
  if (segs.length === 0 || !segs.some((s) => s.kind === 'bay')) return null;
  const p = normalise(L, positionM);
  let i = segs.findIndex((s) => forwardDistance(L, s.startM, p) < s.lengthM);
  if (i < 0) return null;
  let left = segs[i]!.lengthM - forwardDistance(L, segs[i]!.startM, p);
  let leftBay = segs[i]!.kind !== 'bay';
  let state = loaded;
  const legs: PathLegs = { distanceM: 0, emptyM: 0, loadedM: 0 };
  for (let steps = 0; steps <= 2 * segs.length + 1; steps++) {
    const s = segs[i]!;
    legs.distanceM += left;
    if (state) legs.loadedM += left; else legs.emptyM += left;
    if (s.kind === 'load' && !state) state = true;
    else if (s.kind === 'dump' && state) state = false;
    i = (i + 1) % segs.length;
    const next = segs[i]!;
    if (next.kind !== 'bay') leftBay = true;
    else if (leftBay) return legs;
    left = next.lengthM;
  }
  return null;
}

export type BatteryWarning = 'DEPLETED' | 'CANNOT_REACH_BAY' | 'WONT_FINISH_LAP';
