const dir = '/Volumes/Transcend/control_room/.claude/worktrees/agent-a6d60eb5301694af6/research/fixtures/';
for (const f of readdirSync(dir).filter((x) => x.endsWith('.jsonl') && !x.startsWith('._'))) {
  const recs = readFileSync(dir + f, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
  const sends = [];
  for (const r of recs) {
