      const s = sends.filter((x) => x.id === r.m.command_id && x.at <= r.rx_ms).at(-1);
      console.log(f, r.m.command_id, s?.action, r.m.status, r.m.reason ?? '', 'stamp-send', s ? r.m.server_time_ms - s.at : '?', 'rx-send', s ? r.rx_ms - s.at : '?', 'rx-stamp', r.rx_ms - r.m.server_time_ms);
    }
  }
  const unacked = sends.filter((s) => !recs.some((r) => r.kind === 'msg' && r.m.type === 'command_ack' && r.m.command_id === s.id));
  for (const s of unacked) console.log(f, s.id, s.action, 'NO ACK');
}

