    assert.equal(r.link.status().authError, 'TOO_MANY_CONNECTIONS');
    assert.equal(r.link.status().state, 'down');
    assert.equal(r.link.status().nextAttemptAtMs! - r.clock.now(), PARAMS.linkBackoffBusyBase.value);
