test('L5 link drop, during CLOSING (fixture link-drop-in-notice): on reconnect the zone is still closing, with the time left recalculated', () => {
  const r = linkRig({ blasts: [{ zoneId: 'DRAW_12', atMs: 5_000, closedForMs: 60_000 }] });
  try {
    r.link.start();
    r.advance(6_000);
