    assert.equal(r.dialer.sentLines.length, 0);
  } finally { r.cleanup(); }
});

test('configuration comes from GATEWAY_HOST, GATEWAY_PORT and GATEWAY_EMAIL, and errors never echo a value', () => {
  assert.deepEqual(linkConfigFromEnv({ GATEWAY_HOST: 'h', GATEWAY_PORT: '443', GATEWAY_EMAIL: '<redacted-email>' }), { host: 'h', port: 443, email: '<redacted-email>' });
