  try { linkConfigFromEnv({ GATEWAY_HOST: 'h', GATEWAY_PORT: 'secret-ish', GATEWAY_EMAIL: '<redacted-email>' }); } catch (e) {
    assert.ok(!String(e).includes('secret-ish') && !String(e).includes('<redacted-email>'));
  }
});

